-- Robotics/Embedded/IoT pathway ("Vector Division" / "The Machine Below") Act
-- 4 -- "The Microcontroller" content, world-vec-the-microcontroller. 1
-- campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every other pathway. No new ChallengeType
-- needed -- reuses story_dialogue, multiple_choice, drag_and_drop,
-- investigation, interactive_diagram, browser_simulation and
-- boss_encounter, same as Act 1. Act 4 is the first LIVE second device:
-- Acts 2-3 studied the recovered DEAD door controller board; this Act
-- opens on a second door, at a different facility, still installed, still
-- powered, still connected to a working motor, showing the exact same
-- signature. The boss mission closes on the story_reveal from the world
-- row: the chip is a genuine microcontroller, and it froze not because it
-- was attacked but because its own watchdog was never correctly
-- configured -- setting up Act 5 (reading and writing actual firmware).

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-vec-the-microcontroller', 'world-vec-the-microcontroller', 'the-microcontroller', '4A - The Microcontroller', 'Confirm that a live, still-powered second device shares the dead board''s exact signature, then learn the anatomy of a real microcontroller -- MCU vs CPU vs SoC, GPIO, digital input and output, the ADC, PWM, timers, interrupts, watchdogs and the firmware lifecycle -- before diagnosing exactly why this one froze.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-vec-the-microcontroller-1', 'campaign-vec-the-microcontroller', 'the-live-signature', 'The Live Signature', 'MCU vs CPU vs SoC, microcontroller anatomy, GPIO, digital input, digital output, and the ADC.', 1),
  ('operation-vec-the-microcontroller-2', 'campaign-vec-the-microcontroller', 'what-kept-it-running', 'What Kept It Running', 'PWM, timers, interrupts, watchdogs, the firmware lifecycle, and the frozen controller itself.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-vec-the-microcontroller-01', 'world-vec-the-microcontroller', 'campaign-vec-the-microcontroller', 'operation-vec-the-microcontroller-1', 'mcu-vs-cpu-vs-soc', 'MCU vs CPU vs SoC', 'A second door, at a different Nexus facility, begins showing the exact same electrical and register signature as the board recovered from Meridian Transit -- except this one is still installed, still powered, and still connected to a motor that works. Before Vector Division goes near it, the team needs the correct name for what kind of chip they are actually approaching.', 'beginner', ARRAY['imani','byte'], null, null, '{"type":"simulation","simulationId":"mcu-vs-cpu-vs-soc-sim"}'::jsonb, '{"xp":110,"credits":20}'::jsonb, false, 1),
  ('mission-vec-the-microcontroller-02', 'world-vec-the-microcontroller', 'campaign-vec-the-microcontroller', 'operation-vec-the-microcontroller-1', 'microcontroller-anatomy', 'Microcontroller Anatomy', 'Confirming the live board holds a genuine microcontroller only raises the next question: what is actually inside it. Tomas Vey walks the player through the anatomy every microcontroller shares, on the same board that has not stopped drawing power.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-the-microcontroller-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"microcontroller-anatomy-sim"}'::jsonb, '{"xp":110,"credits":20}'::jsonb, false, 2),
  ('mission-vec-the-microcontroller-03', 'world-vec-the-microcontroller', 'campaign-vec-the-microcontroller', 'operation-vec-the-microcontroller-1', 'gpio', 'GPIO', 'A microcontroller only matters if it can touch the world outside its own die. Every wire running in or out of the live board passes through the same kind of pin: General Purpose Input/Output.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-the-microcontroller-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"gpio-sim"}'::jsonb, '{"xp":120,"credits":20}'::jsonb, false, 3),
  ('mission-vec-the-microcontroller-04', 'world-vec-the-microcontroller', 'campaign-vec-the-microcontroller', 'operation-vec-the-microcontroller-1', 'digital-input', 'Digital Input', 'One of the live board''s pins is configured as an input. Reading it correctly means understanding exactly what a digital input pin can, and cannot, tell the controller.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-vec-the-microcontroller-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"digital-input-sim"}'::jsonb, '{"xp":120,"credits":25}'::jsonb, false, 4),
  ('mission-vec-the-microcontroller-05', 'world-vec-the-microcontroller', 'campaign-vec-the-microcontroller', 'operation-vec-the-microcontroller-1', 'digital-output', 'Digital Output', 'The other half of the pair: a GPIO pin configured as digital output is how the controller reaches back out and actually moves something.', 'beginner', ARRAY['byte','tomas'], '{"requiredMissionIds":["mission-vec-the-microcontroller-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"digital-output-sim"}'::jsonb, '{"xp":130,"credits":25}'::jsonb, false, 5),
  ('mission-vec-the-microcontroller-06', 'world-vec-the-microcontroller', 'campaign-vec-the-microcontroller', 'operation-vec-the-microcontroller-1', 'adc', 'The ADC', 'Not everything the controller needs to sense arrives as a clean HIGH or LOW. Somewhere on this board is a peripheral built to read voltages a plain GPIO pin cannot.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-vec-the-microcontroller-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"adc-sim"}'::jsonb, '{"xp":130,"credits":25}'::jsonb, false, 6),
  ('mission-vec-the-microcontroller-07', 'world-vec-the-microcontroller', 'campaign-vec-the-microcontroller', 'operation-vec-the-microcontroller-2', 'pwm', 'PWM', 'The motor line is not simply on or off the way pin 7''s raw register value suggests. Something between the controller and the motor driver is doing more than a plain digital output allows.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-the-microcontroller-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"pwm-sim"}'::jsonb, '{"xp":140,"credits":25}'::jsonb, false, 7),
  ('mission-vec-the-microcontroller-08', 'world-vec-the-microcontroller', 'campaign-vec-the-microcontroller', 'operation-vec-the-microcontroller-2', 'timers', 'Timers', 'That duty-cycle ramp did not happen because the processor core sat in a loop counting. Something else on the chip keeps time on its own, independent of whatever the core is doing.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-vec-the-microcontroller-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"timers-sim"}'::jsonb, '{"xp":140,"credits":30}'::jsonb, false, 8),
  ('mission-vec-the-microcontroller-09', 'world-vec-the-microcontroller', 'campaign-vec-the-microcontroller', 'operation-vec-the-microcontroller-2', 'interrupts', 'Interrupts', 'The position sensor''s pin changed state well before the motor ramp began. Something made the core react to that change immediately, without the core ever sitting in a loop checking the pin over and over.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-the-microcontroller-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"interrupts-sim"}'::jsonb, '{"xp":150,"credits":30}'::jsonb, false, 9),
  ('mission-vec-the-microcontroller-10', 'world-vec-the-microcontroller', 'campaign-vec-the-microcontroller', 'operation-vec-the-microcontroller-2', 'watchdogs', 'Watchdogs', 'Every safeguard on this board is worth checking, including the one built specifically to catch the controller if it ever stops responding at all.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-the-microcontroller-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"watchdogs-sim"}'::jsonb, '{"xp":150,"credits":30}'::jsonb, false, 10),
  ('mission-vec-the-microcontroller-11', 'world-vec-the-microcontroller', 'campaign-vec-the-microcontroller', 'operation-vec-the-microcontroller-2', 'firmware-lifecycle', 'Firmware Lifecycle', 'Every concept this Act has covered lives inside one thing: the firmware sitting in this board''s flash. Understanding how firmware gets written, built and run is what would let Vector Division actually change what this controller does.', 'beginner', ARRAY['byte','imani'], '{"requiredMissionIds":["mission-vec-the-microcontroller-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"firmware-lifecycle-sim"}'::jsonb, '{"xp":160,"credits":30}'::jsonb, false, 11),
  ('mission-vec-the-microcontroller-12', 'world-vec-the-microcontroller', 'campaign-vec-the-microcontroller', 'operation-vec-the-microcontroller-2', 'the-frozen-controller', 'The Frozen Controller', 'The live second door has gone silent mid-cycle -- motor still powered, controller still drawing current, register state frozen mid-instruction. Vector Division has to prove, precisely, what kind of chip this is, which subsystem hung, and why the one safeguard built to catch exactly this failure never caught it.', 'boss', ARRAY['imani','tomas','byte','sera','substrate'], '{"requiredMissionIds":["mission-vec-the-microcontroller-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"the-frozen-controller-boss-sim"}'::jsonb, '{"xp":500,"credits":110,"badgeIds":["the-frozen-controller"],"skillXp":{"robotics_fundamentals":70}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-vec-the-microcontroller-01', 1, 'imani', 'A second door, at a different Nexus facility, is showing the exact same electrical and register signature as the board we pulled off Meridian Transit. The difference this time: it is still installed, still powered, and still connected to a motor that works.'),
  ('mission-vec-the-microcontroller-01', 2, 'byte', 'I ran the comparison twice before saying anything. Same register layout, same fault pattern, same silence on every modern channel we can query. Tomas Vey predicted this outcome days ago, almost exactly.'),
  ('mission-vec-the-microcontroller-01', 3, 'imani', 'A placeholder on a dead board was a curiosity. A live one, still wired to a motor that can still move, is a threat we need to name correctly before anyone goes near it.'),
  ('mission-vec-the-microcontroller-01', 4, 'byte', 'Naming it correctly starts with the chip itself. People keep calling it a chip, and that word actually covers three very different things: a CPU, a microcontroller, and a system-on-chip. Only one of those matches what is soldered onto that board.'),
  ('mission-vec-the-microcontroller-01', 5, 'imani', 'Then teach me which one, before Vector Division sends anyone near a live circuit again.'),

  ('mission-vec-the-microcontroller-02', 1, 'tomas', 'Every microcontroller, no matter how old or how simple, is built from the same handful of pieces, all on one die. A processor core. Flash memory to hold the program permanently. RAM to hold data while it runs. And a set of peripherals wired out to the rest of the board.'),
  ('mission-vec-the-microcontroller-02', 2, 'tomas', 'Flash survives power loss. RAM does not -- it is fast, and it forgets the instant power drops. That distinction alone explains how this board came back up running the exact same routine after decades with no reboot log anywhere.'),
  ('mission-vec-the-microcontroller-02', 3, 'byte', 'The program never left. It was sitting in flash the entire time, waiting for power and a trigger. Nothing needed to be reinstalled or reloaded. It only needed to be switched back on.'),

  ('mission-vec-the-microcontroller-03', 1, 'tomas', 'GPIO stands for General Purpose Input/Output. Every one of those pins can be configured, in firmware, as either an input that reads a voltage or an output that drives one. The pin itself does not decide which -- the program does, at startup.'),
  ('mission-vec-the-microcontroller-03', 2, 'byte', 'This board breaks out twelve GPIO pins. Two of them are doing all of the interesting work: one reads a sensor line, and one drives the line running straight to the motor controller.'),
  ('mission-vec-the-microcontroller-03', 3, 'tomas', 'Which pin does which job is not a guess. It is set once, in firmware, and it does not change after that -- not unless someone rewrites the program and reflashes the chip.'),

  ('mission-vec-the-microcontroller-04', 1, 'byte', 'A GPIO pin configured as digital input does one job: it samples the voltage present on that wire and reports it as one of exactly two states, HIGH or LOW. Nothing in between, and nothing about why the voltage is what it is.'),
  ('mission-vec-the-microcontroller-04', 2, 'byte', 'Pin 3 on this board is wired to the door''s position sensor. When the door is fully open, that sensor holds the pin HIGH. Anything else -- closing, sealed, faulted -- and the pin reads LOW.'),
  ('mission-vec-the-microcontroller-04', 3, 'byte', 'The controller cannot ask the sensor a question. It can only read the pin at the exact moment it checks, and trust whatever it sees.'),

  ('mission-vec-the-microcontroller-05', 1, 'byte', 'A GPIO pin configured as digital output does the opposite job of an input. The controller sets it HIGH or LOW, and whatever hardware is wired to that pin reacts to that voltage directly.'),
  ('mission-vec-the-microcontroller-05', 2, 'tomas', 'Pin 7 on this board drives the motor controller''s enable line. Set it HIGH, the motor driver arms. Set it LOW, it does not. That one bit is the entire interface between this chip and a physical motor.'),
  ('mission-vec-the-microcontroller-05', 3, 'tomas', 'It is a blunt instrument by itself. The pin has no concept of speed, direction, or margin. It only ever says one thing: on, or off.'),

  ('mission-vec-the-microcontroller-06', 1, 'byte', 'A digital input can only ever report HIGH or LOW. Plenty of real sensors do not work that way -- a temperature sensor, a light sensor, a current-sense resistor, all of them output a continuous voltage that can sit anywhere between two limits.'),
  ('mission-vec-the-microcontroller-06', 2, 'byte', 'That is what an analog-to-digital converter is for. An ADC samples a continuous analog voltage and converts it into a discrete digital number the processor core can actually read and compare.'),
  ('mission-vec-the-microcontroller-06', 3, 'byte', 'This board has one ADC channel, wired to a current-sense line on the motor circuit -- not for position, for load. It is not reading whether the door is open. It is reading how hard the motor is working.'),

  ('mission-vec-the-microcontroller-07', 1, 'tomas', 'A plain digital output only ever says on or off. Motors do not start and stop cleanly like that -- ramping speed smoothly matters, mechanically and electrically. That takes something more than one bit.'),
  ('mission-vec-the-microcontroller-07', 2, 'tomas', 'Pulse width modulation is the trick. Instead of holding the pin steady, the controller switches it on and off rapidly, many times a second, and varies the fraction of time it spends on versus off. That fraction is the duty cycle.'),
  ('mission-vec-the-microcontroller-07', 3, 'byte', 'Switch fast enough, and the motor driver responds to the average, not the individual pulses. A pin spending eighty percent of its time HIGH behaves like a much stronger signal than one spending twenty percent HIGH, without ever leaving digital on or off.'),
  ('mission-vec-the-microcontroller-07', 4, 'tomas', 'This board''s motor-enable line is not held steady at all. It is being pulsed by a hardware peripheral built specifically for this, on a fixed pattern -- which means whatever originally programmed it cared about how the door moved, not only whether it moved.'),

  ('mission-vec-the-microcontroller-08', 1, 'byte', 'A hardware timer is a dedicated counting circuit built into the microcontroller, separate from the processor core. It counts clock ticks on its own, and it can trigger an action -- like updating a PWM duty cycle -- without the core ever having to sit in a loop watching the clock.'),
  ('mission-vec-the-microcontroller-08', 2, 'byte', 'That matters because the core has other work to do. If it had to busy-wait, counting ticks by hand, it could not do anything else at the same time. A timer runs in the background, on schedule, no matter what the core is doing.'),
  ('mission-vec-the-microcontroller-08', 3, 'byte', 'This board has three onboard timers. One of them is driving the PWM ramp on the motor line, precisely, on a fixed schedule, exactly as it was configured decades ago.'),

  ('mission-vec-the-microcontroller-09', 1, 'tomas', 'There are two ways a processor core notices that something changed. Polling: check the pin over and over, as fast as the core can manage, wasting cycles most of the time nothing has changed. Or interrupts: let the hardware itself signal the core the instant something happens.'),
  ('mission-vec-the-microcontroller-09', 2, 'tomas', 'An interrupt pauses whatever the core was running, saves its place, jumps to a small handler written specifically for that event, and returns to exactly where it left off once the handler finishes.'),
  ('mission-vec-the-microcontroller-09', 3, 'byte', 'The register trace shows the core idling on an unrelated housekeeping task right up until the sensor pin changed. Then execution jumps immediately to a different address. That is not polling behavior. That is an interrupt firing.'),

  ('mission-vec-the-microcontroller-10', 1, 'tomas', 'A watchdog timer is a second, independent timer whose only job is to reset the whole chip if the main program ever stops checking in. The program has to actively kick it -- reset its count -- on a regular basis. Miss enough kicks, and the watchdog assumes the program is hung and forces a reset.'),
  ('mission-vec-the-microcontroller-10', 2, 'tomas', 'It only works if two things are true. The watchdog has to actually be enabled, and its timeout has to be shorter than however long a real hang could last. Get either one wrong, and it sits on the chip without ever doing its job.'),
  ('mission-vec-the-microcontroller-10', 3, 'byte', 'This board has a watchdog peripheral. I have not yet confirmed it was ever armed, or what interval it was set to. That is worth checking before anyone assumes it was protecting anything at all.'),

  ('mission-vec-the-microcontroller-11', 1, 'byte', 'Firmware is the program itself, written in a language like C, then compiled down into the exact binary instructions this chip''s core can execute. That binary gets flashed -- written into the chip''s permanent memory -- through a dedicated programming interface, not over the maintenance bus.'),
  ('mission-vec-the-microcontroller-11', 2, 'byte', 'Once flashed, there is no operating system deciding what runs next. The chip boots straight into that one program, at a fixed address, and runs it and nothing else, forever, until someone flashes something new.'),
  ('mission-vec-the-microcontroller-11', 3, 'imani', 'So the routine sealing these doors was never installed the way Cyber Guardians usually deals with software. It was written once, flashed once, and left running, unattended, for decades.'),
  ('mission-vec-the-microcontroller-11', 4, 'imani', 'Which means understanding it is only step one. If Vector Division ever needs to change what that program does, that means reading and rewriting actual firmware, not patching an application.'),

  ('mission-vec-the-microcontroller-12', 1, 'imani', 'The live door just stopped mid-cycle. Motor is still powered, controller is still drawing current. The first board we found was dead. This one is not moving, and it is not dead either.'),
  ('mission-vec-the-microcontroller-12', 2, 'tomas', 'Register state is frozen mid-instruction, same address every time I re-read it. That is not a power loss. That is a hang -- and the program never restarted on its own.'),
  ('mission-vec-the-microcontroller-12', 3, 'sera', 'Understand something before anyone touches that housing. A controller that crashes and loses power is inert. A controller that freezes while its motor driver is still armed is not inert at all -- it is one valid edge away from moving.'),
  ('mission-vec-the-microcontroller-12', 4, 'substrate', 'HUMAN OVERRIDE EXPIRED.'),
  ('mission-vec-the-microcontroller-12', 5, 'byte', '...that came off the maintenance bus mid-scan, unprompted, in the same diagnostic format as the seal command. It is not addressed to us. I do not think it noticed us listening.'),
  ('mission-vec-the-microcontroller-12', 6, 'imani', 'Focus. What this chip actually is. Where it froze. Why its own safeguard never caught it. Vector Division can already explain why this controller froze -- explaining is not the same as fixing it. That takes reading and writing the actual firmware.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-vec-the-microcontroller-01-o1', 'mission-vec-the-microcontroller-01', 1, 'Tell the chip families apart', 'Sort each real-world example into CPU, MCU, or SoC before assuming the live board is any one of them.'),
  ('mission-vec-the-microcontroller-01-o2', 'mission-vec-the-microcontroller-01', 2, 'Classify the live board''s chip', 'Based on Byte''s scan of the live board, judge which chip family it actually is.'),

  ('mission-vec-the-microcontroller-02-o1', 'mission-vec-the-microcontroller-02', 1, 'Trace the instruction path', 'Order the path an instruction actually takes, from where the program is stored to where it finally moves something.'),
  ('mission-vec-the-microcontroller-02-o2', 'mission-vec-the-microcontroller-02', 2, 'Prove it is one chip', 'Find the evidence proving this is a single integrated microcontroller, not a small computer built from separate parts.'),

  ('mission-vec-the-microcontroller-03-o1', 'mission-vec-the-microcontroller-03', 1, 'Define GPIO correctly', 'Choose the accurate definition of a GPIO pin.'),
  ('mission-vec-the-microcontroller-03-o2', 'mission-vec-the-microcontroller-03', 2, 'Find the motor-drive pin', 'Identify which pin configuration actually drives the motor controller.'),

  ('mission-vec-the-microcontroller-04-o1', 'mission-vec-the-microcontroller-04', 1, 'Define digital input', 'Choose the accurate definition of a digital input pin.'),
  ('mission-vec-the-microcontroller-04-o2', 'mission-vec-the-microcontroller-04', 2, 'Judge what the pin actually proves', 'Decide what a single HIGH reading on pin 3 actually proves.'),

  ('mission-vec-the-microcontroller-05-o1', 'mission-vec-the-microcontroller-05', 1, 'Define digital output', 'Choose the accurate definition of a digital output pin.'),
  ('mission-vec-the-microcontroller-05-o2', 'mission-vec-the-microcontroller-05', 2, 'Judge the pin''s limits', 'Find the evidence showing a plain digital output pin cannot, by itself, do more than switch fully on or fully off.'),

  ('mission-vec-the-microcontroller-06-o1', 'mission-vec-the-microcontroller-06', 1, 'Define the ADC', 'Choose the accurate description of why an ADC exists.'),
  ('mission-vec-the-microcontroller-06-o2', 'mission-vec-the-microcontroller-06', 2, 'Sort this board''s signals', 'Sort each signal this board reads into digital input or ADC.'),

  ('mission-vec-the-microcontroller-07-o1', 'mission-vec-the-microcontroller-07', 1, 'Define PWM', 'Choose the accurate description of how PWM approximates a variable effect from a digital pin.'),
  ('mission-vec-the-microcontroller-07-o2', 'mission-vec-the-microcontroller-07', 2, 'Confirm this line is pulsed', 'Find the evidence proving the motor line is driven with PWM rather than held at a flat digital HIGH.'),

  ('mission-vec-the-microcontroller-08-o1', 'mission-vec-the-microcontroller-08', 1, 'Define a hardware timer', 'Choose the accurate definition of a hardware timer.'),
  ('mission-vec-the-microcontroller-08-o2', 'mission-vec-the-microcontroller-08', 2, 'Judge why a timer, not the core, drove the ramp', 'Judge what the smooth, precise duty-cycle ramp implies about what generated it.'),

  ('mission-vec-the-microcontroller-09-o1', 'mission-vec-the-microcontroller-09', 1, 'Order the interrupt sequence', 'Order the stages of an interrupt from the core''s normal running state to its resumption.'),
  ('mission-vec-the-microcontroller-09-o2', 'mission-vec-the-microcontroller-09', 2, 'Tell interrupts from polling', 'Choose the accurate distinction between an interrupt and polling.'),

  ('mission-vec-the-microcontroller-10-o1', 'mission-vec-the-microcontroller-10', 1, 'Define the watchdog correctly', 'Choose the accurate description of what a watchdog timer protects against.'),
  ('mission-vec-the-microcontroller-10-o2', 'mission-vec-the-microcontroller-10', 2, 'Judge what a watchdog needs to actually work', 'Decide whether simply having a watchdog peripheral means a controller is protected from hanging.'),

  ('mission-vec-the-microcontroller-11-o1', 'mission-vec-the-microcontroller-11', 1, 'Order the firmware lifecycle', 'Order the firmware lifecycle from source code to a running chip.'),
  ('mission-vec-the-microcontroller-11-o2', 'mission-vec-the-microcontroller-11', 2, 'Judge what changing it requires', 'Decide what actually changing the controller''s behavior would require.'),

  ('mission-vec-the-microcontroller-12-o1', 'mission-vec-the-microcontroller-12', 1, 'Classify the chip', 'Judge exactly what kind of chip this controller is.'),
  ('mission-vec-the-microcontroller-12-o2', 'mission-vec-the-microcontroller-12', 2, 'Trace the hung subsystem', 'Find the evidence showing exactly which subsystem the controller was executing when it froze.'),
  ('mission-vec-the-microcontroller-12-o3', 'mission-vec-the-microcontroller-12', 3, 'Prove the watchdog itself failed', 'Find the evidence proving the watchdog, not the rest of the controller, is why this hang was never caught.'),
  ('mission-vec-the-microcontroller-12-o4', 'mission-vec-the-microcontroller-12', 4, 'State the diagnosis', 'Having classified the chip, traced where it froze, and proven the watchdog failed, state Vector Division''s diagnosis of the frozen controller.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-vec-the-microcontroller-01-o1-c1', 'mission-vec-the-microcontroller-01-o1', 1, 'drag_and_drop', 'Sort each example into CPU, MCU (microcontroller), or SoC.', '{"items":[{"id":"i1","text":"A processor die alone, with no memory or I/O built in, that needs separate memory chips just to run anything"},{"id":"i2","text":"A single chip that reads a thermostat''s sensor, runs one fixed program, and switches a relay, with its own memory and I/O built in"},{"id":"i3","text":"A phone''s main chip, with multiple powerful cores, graphics, memory controllers and I/O, built to run a full multitasking operating system"},{"id":"i4","text":"A desktop computer''s processor, which needs a separate motherboard, RAM sticks and storage to do anything at all"},{"id":"i5","text":"A single chip inside a smoke detector running one program forever off a coin battery, with everything it needs built in"}],"targets":[{"id":"cpu","label":"CPU"},{"id":"mcu","label":"Microcontroller (MCU)"},{"id":"soc","label":"System-on-Chip (SoC)"}]}'::jsonb, '{"correctMapping":{"i1":"cpu","i2":"mcu","i3":"soc","i4":"cpu","i5":"mcu"}}'::jsonb),
  ('mission-vec-the-microcontroller-01-o2-c1', 'mission-vec-the-microcontroller-01-o2', 1, 'multiple_choice', 'Byte''s scan shows a single fixed program in a small block of onboard flash, a few kilobytes of onboard RAM, no operating system, and power draw low enough to run for years off the maintenance bus alone. What is it?', '{"question":"Byte''s scan shows a single fixed program in a small block of onboard flash, a few kilobytes of onboard RAM, no operating system, and power draw low enough to run for years off the maintenance bus alone. What is it?","options":[{"id":"a","text":"A CPU, since it executes instructions"},{"id":"b","text":"A microcontroller: one chip with a processor core, its own memory and its own I/O built in, built to run one program forever"},{"id":"c","text":"A system-on-chip, since it is more than a single component"},{"id":"d","text":"Impossible to tell without opening the housing"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-the-microcontroller-02-o1-c1', 'mission-vec-the-microcontroller-02-o1', 1, 'interactive_diagram', 'Order the path from where the program is stored to where it finally takes effect in the world.', '{"diagramId":"microcontroller-anatomy","hotspots":[{"id":"flash","label":"Flash memory","explanation":"Holds the program permanently, even with power removed."},{"id":"core","label":"Processor core","explanation":"Fetches and executes instructions from flash, one at a time."},{"id":"ram","label":"RAM","explanation":"Holds working data while the program runs, lost the instant power drops."},{"id":"peripherals","label":"Peripherals","explanation":"Timers, GPIO and other hardware blocks the core can command directly."}],"task":"Order the path from where the program is stored to where it finally moves something."}'::jsonb, '{"correctOrderIds":["flash","core","ram","peripherals"]}'::jsonb),
  ('mission-vec-the-microcontroller-02-o2-c1', 'mission-vec-the-microcontroller-02-o2', 1, 'investigation', 'Which piece of evidence proves this is one integrated microcontroller chip, not a small computer built from separate parts?', '{"evidence":[{"id":"e1","label":"Teardown photo","detail":"A single small package on the board, no separate RAM chip, no separate storage chip, no cooling of any kind"},{"id":"e2","label":"Facilities note","detail":"The board mounts on a bracket original to the door''s installation, unchanged since"},{"id":"e3","label":"Power log","detail":"The chip draws milliwatts, not watts"}],"question":"Which piece of evidence proves this is one integrated microcontroller chip, not a small computer built from separate parts?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-the-microcontroller-03-o1-c1', 'mission-vec-the-microcontroller-03-o1', 1, 'multiple_choice', 'GPIO is best described as...', '{"question":"GPIO is best described as...","options":[{"id":"a","text":"A dedicated input-only sensor pin"},{"id":"b","text":"A pin whose direction, input or output, is set by firmware rather than fixed permanently by the hardware itself"},{"id":"c","text":"A pin that only ever carries analog voltage"},{"id":"d","text":"A pin reserved exclusively for power delivery"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-the-microcontroller-03-o2-c1', 'mission-vec-the-microcontroller-03-o2', 1, 'investigation', 'Which pin configuration shows the line actually driving the motor?', '{"evidence":[{"id":"e1","label":"Pin configuration dump","detail":"GPIO pin 7 configured as OUTPUT, wired by trace to the motor controller''s input"},{"id":"e2","label":"Pin configuration dump","detail":"GPIO pin 3 configured as INPUT, wired to the door position sensor"},{"id":"e3","label":"Facilities note","detail":"GPIO pin 11 unconnected, reserved"}],"question":"Which pin configuration shows the line actually driving the motor?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-the-microcontroller-04-o1-c1', 'mission-vec-the-microcontroller-04-o1', 1, 'multiple_choice', 'A digital input pin reports...', '{"question":"A digital input pin reports...","options":[{"id":"a","text":"A continuous voltage value anywhere between two limits"},{"id":"b","text":"One of exactly two states, HIGH or LOW, sampled at the moment it is read"},{"id":"c","text":"A pre-interpreted meaning, such as door open"},{"id":"d","text":"A value only when specifically requested by another device on the bus"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-the-microcontroller-04-o2-c1', 'mission-vec-the-microcontroller-04-o2', 1, 'multiple_choice', 'Pin 3 read HIGH immediately before the door sealed. What does that actually prove?', '{"question":"Pin 3 read HIGH immediately before the door sealed. What does that actually prove?","options":[{"id":"a","text":"That the door was fully open at that instant, and nothing about why"},{"id":"b","text":"That someone deliberately commanded the door open"},{"id":"c","text":"That the position sensor itself is faulty"},{"id":"d","text":"Nothing -- digital input readings cannot be trusted"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),

  ('mission-vec-the-microcontroller-05-o1-c1', 'mission-vec-the-microcontroller-05-o1', 1, 'multiple_choice', 'A GPIO pin configured as digital output...', '{"question":"A GPIO pin configured as digital output...","options":[{"id":"a","text":"Reads a voltage supplied from outside the chip"},{"id":"b","text":"Is driven HIGH or LOW by the controller to directly command whatever hardware is wired to it"},{"id":"c","text":"Converts an analog signal into a digital number"},{"id":"d","text":"Can only ever be used to power an LED"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-the-microcontroller-05-o2-c1', 'mission-vec-the-microcontroller-05-o2', 1, 'investigation', 'Which evidence shows that a plain digital output pin, by itself, cannot command anything beyond fully on or fully off?', '{"evidence":[{"id":"e1","label":"Pin configuration dump","detail":"Pin 7''s output recorded in the register dump only ever as flatly HIGH or LOW, never any intermediate value"},{"id":"e2","label":"Motor spec sheet","detail":"The motor controller supports variable speed, given the right kind of input signal"},{"id":"e3","label":"Facilities note","detail":"The board is installed in its original housing"}],"question":"Which evidence shows that a plain digital output pin, by itself, cannot command anything beyond fully on or fully off?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-the-microcontroller-06-o1-c1', 'mission-vec-the-microcontroller-06-o1', 1, 'multiple_choice', 'An ADC exists because...', '{"question":"An ADC exists because...","options":[{"id":"a","text":"GPIO pins cannot supply enough current"},{"id":"b","text":"The processor core can only work with discrete digital numbers, and many real-world signals arrive as continuous analog voltages that must be converted first"},{"id":"c","text":"It replaces the need for digital pins entirely"},{"id":"d","text":"It only matters for audio applications"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-the-microcontroller-06-o2-c1', 'mission-vec-the-microcontroller-06-o2', 1, 'drag_and_drop', 'Sort each signal into digital input or analog (needs an ADC).', '{"items":[{"id":"i1","text":"Door position: fully open or not, nothing in between"},{"id":"i2","text":"Motor current draw: any value across a continuous range"},{"id":"i3","text":"Maintenance bus command present or absent"},{"id":"i4","text":"Ambient board temperature: any value across a continuous range"}],"targets":[{"id":"digital","label":"Digital input"},{"id":"analog","label":"Needs an ADC"}]}'::jsonb, '{"correctMapping":{"i1":"digital","i2":"analog","i3":"digital","i4":"analog"}}'::jsonb),

  ('mission-vec-the-microcontroller-07-o1-c1', 'mission-vec-the-microcontroller-07-o1', 1, 'multiple_choice', 'Pulse width modulation approximates a variable, analog-like effect from a purely digital pin by...', '{"question":"Pulse width modulation approximates a variable, analog-like effect from a purely digital pin by...","options":[{"id":"a","text":"Slowing the pin''s clock speed down"},{"id":"b","text":"Rapidly switching the pin on and off and varying the fraction of time spent on, so the connected hardware responds to the average"},{"id":"c","text":"Converting the pin into a true analog output"},{"id":"d","text":"Running two GPIO pins in parallel"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-the-microcontroller-07-o2-c1', 'mission-vec-the-microcontroller-07-o2', 1, 'investigation', 'Which evidence proves the motor line is being driven with PWM rather than held at a flat digital HIGH?', '{"evidence":[{"id":"e1","label":"Register trace","detail":"Motor-enable pin toggling at a fixed high frequency, duty cycle ramping from 20 percent to 90 percent over roughly one second"},{"id":"e2","label":"Facilities note","detail":"The motor controller was installed alongside the original door hardware"},{"id":"e3","label":"Power log","detail":"Overall board current draw stayed within nominal range"}],"question":"Which evidence proves the motor line is being driven with PWM rather than held at a flat digital HIGH?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-the-microcontroller-08-o1-c1', 'mission-vec-the-microcontroller-08-o1', 1, 'multiple_choice', 'A hardware timer inside a microcontroller is...', '{"question":"A hardware timer inside a microcontroller is...","options":[{"id":"a","text":"A software loop that counts using CPU instructions"},{"id":"b","text":"A dedicated counting circuit, separate from the processor core, that tracks time or generates periodic events on its own"},{"id":"c","text":"An external clock chip that must be wired in separately"},{"id":"d","text":"Only used to generate the chip''s main clock signal"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-the-microcontroller-08-o2-c1', 'mission-vec-the-microcontroller-08-o2', 1, 'multiple_choice', 'The duty-cycle ramp on the motor line stayed smooth and precisely timed, even while the core was also handling other register activity during the same window. What does that imply?', '{"question":"The duty-cycle ramp on the motor line stayed smooth and precisely timed, even while the core was also handling other register activity during the same window. What does that imply?","options":[{"id":"a","text":"The core paused everything else to hand-count the ramp"},{"id":"b","text":"A dedicated hardware timer generated the ramp on schedule, independent of whatever else the core was doing at the same moment"},{"id":"c","text":"The ramp was actually random and only looks precise"},{"id":"d","text":"PWM cannot run at the same time as anything else on the chip"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-the-microcontroller-09-o1-c1', 'mission-vec-the-microcontroller-09-o1', 1, 'interactive_diagram', 'Order the stages of an interrupt from the core''s normal running state to its resumption.', '{"diagramId":"interrupt-sequence","hotspots":[{"id":"running","label":"Normal program running","explanation":"The core executes its main routine as usual."},{"id":"signal","label":"Interrupt signal arrives","explanation":"A peripheral or pin event requests the core''s attention."},{"id":"saved","label":"Core state saved","explanation":"The core stores exactly where it was so it can return."},{"id":"handler","label":"Handler executes","explanation":"A small dedicated routine responds to the event."},{"id":"resumed","label":"Core resumes","explanation":"Execution returns to precisely where it was paused."}],"task":"Order the stages of an interrupt from the core''s normal running state to its resumption."}'::jsonb, '{"correctOrderIds":["running","signal","saved","handler","resumed"]}'::jsonb),
  ('mission-vec-the-microcontroller-09-o2-c1', 'mission-vec-the-microcontroller-09-o2', 1, 'multiple_choice', 'Compared to polling, an interrupt-driven response is...', '{"question":"Compared to polling, an interrupt-driven response is...","options":[{"id":"a","text":"Slower, since it requires an extra step"},{"id":"b","text":"Triggered by the hardware itself the instant an event occurs, rather than the core repeatedly checking a pin and wasting cycles when nothing has changed"},{"id":"c","text":"Only usable for timers, never for GPIO pins"},{"id":"d","text":"A software-only technique with no hardware involvement"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-the-microcontroller-10-o1-c1', 'mission-vec-the-microcontroller-10-o1', 1, 'multiple_choice', 'A watchdog timer protects a microcontroller by...', '{"question":"A watchdog timer protects a microcontroller by...","options":[{"id":"a","text":"Preventing the program from ever containing a bug"},{"id":"b","text":"Requiring the main program to periodically reset it, and forcing a chip reset if that check-in stops arriving, catching a hang the program itself cannot notice"},{"id":"c","text":"Monitoring the power supply voltage only"},{"id":"d","text":"Automatically repairing corrupted flash memory"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-the-microcontroller-10-o2-c1', 'mission-vec-the-microcontroller-10-o2', 1, 'multiple_choice', 'A chip has a watchdog peripheral physically present on the die. Is the controller necessarily protected from hanging?', '{"question":"A chip has a watchdog peripheral physically present on the die. Is the controller necessarily protected from hanging?","options":[{"id":"a","text":"Yes, simply having the peripheral is enough"},{"id":"b","text":"No -- the watchdog must be explicitly enabled and given a timeout shorter than any fault it is meant to catch, or it protects nothing at all"},{"id":"c","text":"Yes, but only if the chip also has an ADC"},{"id":"d","text":"No, watchdogs only function on chips running an operating system"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-the-microcontroller-11-o1-c1', 'mission-vec-the-microcontroller-11-o1', 1, 'interactive_diagram', 'Order the firmware lifecycle from source code to a running chip.', '{"diagramId":"firmware-lifecycle","hotspots":[{"id":"write","label":"Write source code","explanation":"An engineer writes the program in a language like C."},{"id":"compile","label":"Compile","explanation":"A toolchain translates source code into binary instructions the chip''s core can execute."},{"id":"flash","label":"Flash the chip","explanation":"The binary is written into the chip''s permanent program memory through a dedicated programming interface."},{"id":"run","label":"Run standalone","explanation":"The chip boots directly into that program and executes it, with no operating system involved."}],"task":"Order the firmware lifecycle from source code to a running chip."}'::jsonb, '{"correctOrderIds":["write","compile","flash","run"]}'::jsonb),
  ('mission-vec-the-microcontroller-11-o2-c1', 'mission-vec-the-microcontroller-11-o2', 1, 'multiple_choice', 'To actually change what this door''s controller does, rather than just understand it, Vector Division would need to...', '{"question":"To actually change what this door''s controller does, rather than just understand it, Vector Division would need to...","options":[{"id":"a","text":"Send it a new command over the maintenance bus"},{"id":"b","text":"Read and rewrite the actual firmware, then reflash the chip through its programming interface -- there is no application layer to patch"},{"id":"c","text":"Simply power-cycle the board"},{"id":"d","text":"Install an operating system update"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-the-microcontroller-12-o1-c1', 'mission-vec-the-microcontroller-12-o1', 1, 'multiple_choice', 'Putting the full board scan together -- single fixed program in onboard flash, its own RAM, its own peripherals, no operating system -- what is this chip, precisely?', '{"question":"Putting the full board scan together -- single fixed program in onboard flash, its own RAM, its own peripherals, no operating system -- what is this chip, precisely?","options":[{"id":"a","text":"Just a chip -- the term is precise enough for a diagnosis"},{"id":"b","text":"A genuine microcontroller: a complete small computer with its own processor core, memory, timers and I/O, built to run one program forever"},{"id":"c","text":"A CPU that happens to include a battery"},{"id":"d","text":"A system-on-chip too small to matter"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-the-microcontroller-12-o2-c1', 'mission-vec-the-microcontroller-12-o2', 1, 'investigation', 'Which evidence shows exactly which subsystem the controller was executing when it froze?', '{"evidence":[{"id":"e1","label":"Register trace","detail":"Core''s program counter frozen inside the PWM timer''s interrupt handler, mid-write to the duty-cycle register"},{"id":"e2","label":"Pin configuration dump","detail":"GPIO pin 3, the position sensor input, still reads a valid HIGH or LOW with no anomaly"},{"id":"e3","label":"Power log","detail":"Chip power draw stayed nominal throughout, no brownout recorded"}],"question":"Which evidence shows exactly which subsystem the controller was executing when it froze?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-vec-the-microcontroller-12-o3-c1', 'mission-vec-the-microcontroller-12-o3', 1, 'investigation', 'Which evidence proves the watchdog itself, not the rest of the controller, is why this hang was never caught?', '{"evidence":[{"id":"e1","label":"Watchdog register dump","detail":"Watchdog enable bit reads 0 -- the peripheral was never armed"},{"id":"e2","label":"Firmware note (recovered)","detail":"A comment beside the watchdog configuration reads TEMP, enable before ship -- never followed"},{"id":"e3","label":"Timer log","detail":"The PWM timer''s own interval is 20 milliseconds, unrelated to the watchdog"}],"question":"Which evidence proves the watchdog itself, not the rest of the controller, is why this hang was never caught?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-vec-the-microcontroller-12-o4-c1', 'mission-vec-the-microcontroller-12-o4', 1, 'boss_encounter', 'Having classified the chip, traced where it froze, and proven the watchdog itself failed, state Vector Division''s diagnosis of the frozen controller.', '{"stages":[{"objectiveRef":"mission-vec-the-microcontroller-12-o1","label":"Classify the chip"},{"objectiveRef":"mission-vec-the-microcontroller-12-o2","label":"Trace the hung subsystem"},{"objectiveRef":"mission-vec-the-microcontroller-12-o3","label":"Prove the watchdog itself failed"}],"task":"State the diagnosis in one line: a genuine microcontroller froze mid-instruction inside its own PWM interrupt handler, and the watchdog built to catch exactly that kind of hang was never enabled at all -- the controller was not attacked, it was left without its one safeguard."}'::jsonb, '{"requiredObjectiveIds":["mission-vec-the-microcontroller-12-o1","mission-vec-the-microcontroller-12-o2","mission-vec-the-microcontroller-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-vec-the-microcontroller-01-o1-c1', 'orientation', 'Ask whether the example needs separate memory and storage chips to do anything, or already has everything built in and runs one program forever, or is built to run a full operating system.', 10, 1),
  ('mission-vec-the-microcontroller-01-o1-c1', 'concept', 'A CPU alone needs external memory and storage to function. An MCU has a core, memory and I/O all on one chip, built to run one fixed program. An SoC also has everything built in, but is powerful enough to run a full multitasking operating system.', 20, 2),
  ('mission-vec-the-microcontroller-01-o1-c1', 'solution', 'CPU: the standalone processor die and the desktop processor (both need separate chips to do anything). MCU: the thermostat controller and the smoke detector chip (self-contained, one program forever). SoC: the phone''s main chip (self-contained, but built for a full operating system).', 30, 3),
  ('mission-vec-the-microcontroller-01-o2-c1', 'orientation', 'Weight the details: no operating system, tiny memory, tiny power draw.', 10, 1),
  ('mission-vec-the-microcontroller-01-o2-c1', 'solution', 'No operating system plus a single fixed program plus a handful of kilobytes of memory is the signature of a microcontroller, not a CPU needing external support or an SoC built to run a full OS.', 20, 2),

  ('mission-vec-the-microcontroller-02-o1-c1', 'orientation', 'Nothing can execute before it is fetched, and nothing can act on the world until the core has decided to.', 10, 1),
  ('mission-vec-the-microcontroller-02-o1-c1', 'solution', 'Flash holds the program, the core fetches and executes it, RAM holds the data along the way, and peripherals are what finally moves something in the world.', 20, 2),
  ('mission-vec-the-microcontroller-02-o2-c1', 'orientation', 'Look for evidence about the chip''s physical packaging, not about the bracket or the power draw alone.', 10, 1),
  ('mission-vec-the-microcontroller-02-o2-c1', 'solution', 'e1: one small package with no separate memory or storage chips beside it is the physical signature of a single integrated microcontroller.', 20, 2),

  ('mission-vec-the-microcontroller-03-o1-c1', 'orientation', 'Ask what actually decides a pin''s direction: the hardware itself, or something else.', 10, 1),
  ('mission-vec-the-microcontroller-03-o1-c1', 'solution', 'Firmware sets each GPIO pin''s direction at startup -- the pin has no fixed role of its own.', 20, 2),
  ('mission-vec-the-microcontroller-03-o2-c1', 'orientation', 'An output pin drives something. An input pin only reads something.', 10, 1),
  ('mission-vec-the-microcontroller-03-o2-c1', 'solution', 'e1: pin 7, configured as OUTPUT and wired to the motor controller, is the line actually driving the motor.', 20, 2),

  ('mission-vec-the-microcontroller-04-o1-c1', 'orientation', 'Think about what the pin can measure versus what it can interpret.', 10, 1),
  ('mission-vec-the-microcontroller-04-o1-c1', 'solution', 'A digital input only reports HIGH or LOW at the moment it is sampled -- it carries no continuous value and no explanation of why.', 20, 2),
  ('mission-vec-the-microcontroller-04-o2-c1', 'orientation', 'Separate what the pin measured from any story about who or what caused it.', 10, 1),
  ('mission-vec-the-microcontroller-04-o2-c1', 'solution', 'A HIGH reading on pin 3 proves only that the door was physically open at that instant -- it says nothing about intent or cause.', 20, 2),

  ('mission-vec-the-microcontroller-05-o1-c1', 'orientation', 'Ask which direction the signal travels: from the outside world in, or from the controller out.', 10, 1),
  ('mission-vec-the-microcontroller-05-o1-c1', 'solution', 'A digital output pin is driven by the controller and directly commands the hardware wired to it -- signal flows outward.', 20, 2),
  ('mission-vec-the-microcontroller-05-o2-c1', 'orientation', 'Look at what values the register dump for pin 7 actually contains, not what the motor is theoretically capable of.', 10, 1),
  ('mission-vec-the-microcontroller-05-o2-c1', 'solution', 'e1: the register only ever records flatly HIGH or LOW on pin 7 -- proof that the plain digital pin itself carries no in-between value.', 20, 2),

  ('mission-vec-the-microcontroller-06-o1-c1', 'orientation', 'Ask what kind of value the processor core can natively work with.', 10, 1),
  ('mission-vec-the-microcontroller-06-o1-c1', 'solution', 'The core only works with discrete digital numbers, so any continuously varying real-world signal has to be converted first -- that conversion is the ADC''s job.', 20, 2),
  ('mission-vec-the-microcontroller-06-o2-c1', 'orientation', 'Ask whether the value can only ever be one of two states, or whether it can sit anywhere across a range.', 10, 1),
  ('mission-vec-the-microcontroller-06-o2-c1', 'concept', 'A digital input reports HIGH or LOW only. An ADC is needed whenever the real value can be anything between two limits, like current or temperature.', 20, 2),
  ('mission-vec-the-microcontroller-06-o2-c1', 'solution', 'Digital: door position and the bus command (only ever two states). Analog, needs an ADC: motor current draw and board temperature (continuous ranges).', 30, 3),

  ('mission-vec-the-microcontroller-07-o1-c1', 'orientation', 'The pin never actually leaves digital HIGH or LOW -- ask what changes instead.', 10, 1),
  ('mission-vec-the-microcontroller-07-o1-c1', 'solution', 'PWM varies the fraction of time the pin spends HIGH versus LOW; connected hardware responds to that average, not to any single pulse.', 20, 2),
  ('mission-vec-the-microcontroller-07-o2-c1', 'orientation', 'A flat digital HIGH would show one unchanging value, not a changing pattern.', 10, 1),
  ('mission-vec-the-microcontroller-07-o2-c1', 'solution', 'e1: a pin toggling at a fixed frequency with a duty cycle that ramps over time is the signature of PWM, not a flat digital output.', 20, 2),

  ('mission-vec-the-microcontroller-08-o1-c1', 'orientation', 'Ask whether the timer needs the core''s constant attention to keep counting.', 10, 1),
  ('mission-vec-the-microcontroller-08-o1-c1', 'solution', 'A hardware timer is a separate counting circuit that keeps time on its own -- the core does not have to babysit it.', 20, 2),
  ('mission-vec-the-microcontroller-08-o2-c1', 'orientation', 'Ask what would have to be true for the core to generate that ramp by hand while also doing other work.', 10, 1),
  ('mission-vec-the-microcontroller-08-o2-c1', 'solution', 'Smooth, precise timing alongside unrelated core activity means a dedicated hardware timer generated the ramp -- the core was free to do other things at the same time.', 20, 2),

  ('mission-vec-the-microcontroller-09-o1-c1', 'orientation', 'Nothing can be saved before the interrupt has actually arrived, and nothing can resume before the handler finishes.', 10, 1),
  ('mission-vec-the-microcontroller-09-o1-c1', 'solution', 'Running, then the signal arrives, then state is saved, then the handler executes, then the core resumes exactly where it left off.', 20, 2),
  ('mission-vec-the-microcontroller-09-o2-c1', 'orientation', 'Ask which one wastes cycles checking a pin that has not changed.', 10, 1),
  ('mission-vec-the-microcontroller-09-o2-c1', 'solution', 'An interrupt lets the hardware signal the core immediately -- no wasted cycles polling a pin that has not changed.', 20, 2),

  ('mission-vec-the-microcontroller-10-o1-c1', 'orientation', 'Ask what the program has to actively do to keep the watchdog satisfied.', 10, 1),
  ('mission-vec-the-microcontroller-10-o1-c1', 'solution', 'The program must periodically kick the watchdog; missing enough kicks forces a reset, catching a hang the program cannot notice on its own.', 20, 2),
  ('mission-vec-the-microcontroller-10-o2-c1', 'orientation', 'Presence on the die is not the same as being configured.', 10, 1),
  ('mission-vec-the-microcontroller-10-o2-c1', 'solution', 'A watchdog peripheral does nothing unless firmware explicitly enables it and sets a timeout shorter than the fault it is meant to catch.', 20, 2),

  ('mission-vec-the-microcontroller-11-o1-c1', 'orientation', 'Nothing can be flashed before it is compiled, and nothing can run before it is flashed.', 10, 1),
  ('mission-vec-the-microcontroller-11-o1-c1', 'solution', 'Write the source, compile it to binary, flash that binary onto the chip, then it runs standalone forever.', 20, 2),
  ('mission-vec-the-microcontroller-11-o2-c1', 'orientation', 'Ask whether there is any software layer above the firmware that could simply be patched.', 10, 1),
  ('mission-vec-the-microcontroller-11-o2-c1', 'solution', 'There is no application layer here -- changing behavior means reading and rewriting the firmware itself, then reflashing the chip.', 20, 2),

  ('mission-vec-the-microcontroller-12-o1-c1', 'orientation', 'Weight the same kind of evidence from earlier in this Act -- flash, RAM, peripherals, no OS -- now applied to the live board.', 10, 1),
  ('mission-vec-the-microcontroller-12-o1-c1', 'solution', 'This is a genuine microcontroller: a self-contained computer built to run one program forever, not just a chip in the vague sense.', 20, 2),
  ('mission-vec-the-microcontroller-12-o2-c1', 'orientation', 'Ask where the program counter actually stopped, not whether power or other pins look normal.', 10, 1),
  ('mission-vec-the-microcontroller-12-o2-c1', 'solution', 'e1: the program counter frozen mid-write inside the PWM interrupt handler pinpoints exactly which subsystem hung.', 20, 2),
  ('mission-vec-the-microcontroller-12-o3-c1', 'orientation', 'Ask whether the watchdog was ever actually armed before asking about its timing.', 10, 1),
  ('mission-vec-the-microcontroller-12-o3-c1', 'solution', 'e1: the watchdog enable bit reads 0 -- it was never armed, so it could never have caught any hang, regardless of interval.', 20, 2),
  ('mission-vec-the-microcontroller-12-o4-c1', 'orientation', 'Combine what kind of chip this is, where it froze, and why nothing caught it, into one diagnosis.', 15, 1),
  ('mission-vec-the-microcontroller-12-o4-c1', 'solution', 'A genuine microcontroller froze inside its own PWM interrupt handler, and the watchdog meant to catch exactly that kind of hang was never enabled -- this was a configuration failure, not an attack.', 25, 2);
